import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function useCart() {
  const [count, setCount] = useState(0);
  const add = () => setCount((c) => c + 1);
  return { count, add };
}

function App() {
  const cart = useCart();
  return (
    <View style={styles.s}>
      <Text nativeID="count" style={styles.c}>Сагс: {cart.count}</Text>
      <Pressable nativeID="add" style={styles.b} onPress={cart.add}><Text style={styles.t}>Сагслах</Text></Pressable>
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, gap: 16, padding: 24, alignItems: "center", justifyContent: "center" },
  c: { fontSize: 24, fontWeight: "bold" },
  b: { backgroundColor: "#2563eb", padding: 14, borderRadius: 12 }, t: { color: "#fff", fontWeight: "bold" },
});

registerRootComponent(App);
